namespace DogtorBurguer
{
    /// <summary>
    /// Social / Play Games Services configuration. An empty id = not configured:
    /// LeaderboardManager keeps the logging mock even on device builds.
    /// </summary>
    public static class SocialConfig
    {
        // The "High Score" leaderboard (Play Console: Grow → Play Games Services → Leaderboards).
        // GPGSIds is generated by the plugin's Android setup wizard from the Console resources
        // (Docs/play-games-resources.xml) — re-run the wizard to change it, never edit by hand.
        public const string PLAY_GAMES_LEADERBOARD_ID = GPGSIds.leaderboard_high_score;

        /// <summary>True once the leaderboard id is filled in.</summary>
        public static bool LeaderboardConfigured => PLAY_GAMES_LEADERBOARD_ID.Length > 0;
    }
}
